UPDATE outbox_event SET status='SENT',sent_at=CURRENT_TIMESTAMP(6),
    lease_token=NULL,lease_until=NULL,last_error=NULL
WHERE event_id=#{eventId} AND status='PROCESSING' AND lease_token=#{leaseToken}

UPDATE outbox_event SET status='PENDING',
    available_at=TIMESTAMPADD(SECOND,#{delaySeconds},CURRENT_TIMESTAMP(6)),
    lease_token=NULL,lease_until=NULL,last_error=#{error}
WHERE event_id=#{eventId} AND status='PROCESSING' AND lease_token=#{leaseToken}
